          {#if mode==='live'&&baseline&&snapshot?.baselineModel&&populationVisibility!=='live'}<JourneyViews bind:transient={baselineTransient} bind:chosen={baselineTimelineJourney} bind:preferences bind:stages={matrixStages} bind:stagesInitialized={matrixStagesInitialized} bind:expanded={expandedBaseline} bind:criterion={baselineCriterion} view={layout} model={snapshot.baselineModel} {language} {selectedStep} {selectedEdge} onedge={chooseEdge} onjourney={(id)=>openJourney(id,true)} coverage={snapshot?.coverage?.baseline} population="baseline" label="App-wide baseline" commonDomain={lockedDomain} availableStages={[...new Set([...model.journeys,...(snapshot?.baselineModel?.journeys??[])].flatMap(j=>j.steps.map(s=>s.step)))].sort()} onrescale={rescale} ontrace={openTrace} oncriterion={selectCriterion} oncopy={copyInvestigation}/>{/if}
          </div>
        {/if}
