            {#if mode==='live'&&baseline}<div class="button-row"><button class="secondary" aria-pressed={selectedPopulation!=='baseline'} onclick={()=>selectedPopulation='live'}>L · {t('Live')}</button><button class="secondary" aria-pressed={selectedPopulation==='baseline'} onclick={()=>selectedPopulation='baseline'}>B · {t('Baseline')}</button></div>{/if}
            <h2>{selectedEdge?edgeFrom+' → '+edgeTo:currentNode?.label??selectedEvent??selectedStep}</h2>
            {#if selectedEdge&&mode==='live'&&baseline}{#each [['live',currentTransitions],['baseline',baselineTransitions]] as [name,rows]}{@const e=(rows as typeof currentTransitions).find(e=>e.from===edgeFrom&&e.to===edgeTo)}<p>{t(name==='live'?'Live':'Baseline')}: {e?e.occurrences+' '+t('Occurrences')+' / '+e.journeys+' '+t('Journeys')+' / '+e.visits+' '+t('Visits'):t('No observed supporting transition')} <button id={graphInvokerId(name as Population)} class="text-button" disabled={!e} onclick={()=>{graphExamples(name as Population)}}>{t(name==='live'?'Live':'Baseline')} · {t('Show journeys')}</button></p>{/each}{@const l=currentTransitions.find(e=>e.from===edgeFrom&&e.to===edgeTo)}{@const b=baselineTransitions.find(e=>e.from===edgeFrom&&e.to===edgeTo)}{#if !comparisonUnavailable&&l?.denominator&&b?.denominator}<p>{((l.share!-b.share!)*100).toFixed(1)} {t('percentage points')} · {l.denominator} / {b.denominator} {t('Observed outgoing occurrences')}</p>{/if}{/if}
            {#if selectedEdge&&currentEdge}
              <p class="muted">{t(selectedPopulation==='baseline'?'App-wide baseline':mode==='live'?'Live observation':'Current selection')}</p>
              <dl class="inspector-counts"><div><dt>{t('Occurrences')}</dt><dd>{currentEdge.occurrences}</dd></div><div><dt>{t('Journeys')}</dt><dd>{currentEdge.journeys}</dd></div><div><dt>{t('Visits')}</dt><dd>{currentEdge.visits}</dd></div></dl>
              <p class="inspector-note">{t('A transition is observed adjacency, not proof of cause. Open journeys to inspect its order and context.')}</p>
