              <dl class="inspector-counts"><div><dt>{t('Occurrences')}</dt><dd>{currentNode.occurrences}</dd></div><div><dt>{t('Journeys')}</dt><dd>{currentNode.journeys}</dd></div><div><dt>{t('Visits')}</dt><dd>{currentNode.visits}</dd></div></dl>
              {#if currentNode.stops||currentNode.pending}<p class="inspector-note">{currentNode.stops} {t('Potential stops')} · {currentNode.pending} {t('Pending')}<br/>{t('Silence does not establish failure.')}</p>{/if}
              {#each [['Incoming','to','from'],['Outgoing','from','to']] as [label,match,other]}
                <section class="inspector-section"><h3>{t(label)}</h3>{#each nodeEvidenceModel.edges.filter(e=>(e as any)[match]===selectedStep) as edge}<button class="neighbor-row" onclick={()=>chooseEdge(edge.from,edge.to,selectedPopulation)}><span>{(edge as any)[other]===selectedStep?t('Repeated here'):(edge as any)[other]}</span><small>{edge.occurrences} {t('transitions')}</small></button>{:else}<p class="muted">{t('No observed transitions in this selection')}</p>{/each}</section>
              {/each}
              <section class="inspector-section"><h3>{t('Time at stage')}</h3>{#each currentNode.timing??[] as timing}<div class="timing-detail"><span class="subtle-badge">{t(timing.basis==='native-inclusive'?'Native inclusive operation':timing.basis==='measured-elapsed'?'Measured elapsed':timing.basis==='observed-active'?'Observed active':'Next-event estimated')} · v{timing.definition} · {timing.computation??''}</span><dl><div><dt>{t('Median')}</dt><dd>{duration(timing.medianMs,t('Unavailable'))}</dd></div><div><dt>{t('Slower cases (p90)')}</dt><dd>{duration(timing.p90Ms,t('Unavailable'))}</dd></div></dl><small>{timing.samples} {t('samples')} · {timing.excluded} {t('excluded')} · {pct(timing.completeness,1)} {t('complete')}</small></div>{:else}<p class="muted">{t('No completed timing samples')}</p>{/each}<p class="inspector-note">{t('p90 requires 20 completed samples of the same basis. Missing ends are not zero. Elapsed time is not attention.')}</p></section>
              <section class="inspector-section"><h3>{t('Events in this stage')}</h3>{#each nodeMappings as mapping}{#if readOnly}<p class="mono">{mapping.event}</p>{:else}<button class="neighbor-row" onclick={()=>openMapping(mapping.event)}><span>{mapping.event}</span><small>{t('Configure event…')}</small></button>{/if}{/each}</section>
              <div class="inspector-actions"><button id={graphInvokerId(selectedPopulation,'-selected')} class="secondary" onclick={()=>graphExamples()}>{t('Show journeys')} ({contextJourneys.length})</button><button class="quiet-button" onclick={()=>exploreNode('goal-backward')}>{t('Paths into here…')}</button><button class="quiet-button" onclick={()=>exploreNode('origin-forward')}>{t('Paths from here…')}</button><button class="quiet-button" onclick={()=>{segmentStart=eventForStage(selectedStep);selectedStep=''}}>{t('Use as beginning…')}</button></div>
            {:else}<p class="inspector-note">{t('This selection has no retained evidence in the current filters.')}</p>{/if}
          </aside>
        {/if}
      </div>
      <div class="canvas-status"><span>{lastDisplayed?stats.journeys??0:'—'} {t('Journeys')} · {lastDisplayed?stats.completed??0:'—'} {t('Completed goals')} · {lastDisplayed?stats.inactive??0:'—'} {t('Inactive')}<span class="status-extra"> · {lastDisplayed?stats.unassigned??0:'—'} {t('Unassigned records')}</span>{#if mode==='live'&&baseline} · {baselineDisplayed?snapshot?.baselineModel?.stats?.journeys??0:'—'} {t('Baseline journeys')}{/if}</span><div><button class="text-button" onclick={()=>openTool('errors')}>{t('Errors')}</button><button class="text-button" onclick={()=>openTool('table')}>{t('Table')}</button><button class="text-button" onclick={()=>openTool('evidence')}>{t('Journeys & evidence')}</button></div></div>
      {#if graphLensAvailable&&lens==='rare'}<p class="canvas-explanation">{t('Rare: at most 10% of comparable complete paths, with at least 20 closed journeys per definition and version. Low support is not a defect.')} <button class="text-button" onclick={()=>openTool('paths')}>{t('Path counts')}</button></p>{:else if graphLensAvailable&&lens!=='none'}<p class="canvas-explanation">{t(lens==='endings'?'Endings distinguish completed, inactive, explicit exit and pending evidence.':lens==='recovery'?'Recovered journeys retain their earlier warnings and later continuation.':'Warnings and exceptions highlight linked journeys; proximity is not cause.')} <button class="text-button" onclick={()=>openTool('evidence')}>{t('Inspect evidence')}</button></p>{/if}
    </section>
    {/if}
    {#if mappingOpen&&!readOnly}
      <Modal title={t(makeGoal?'Set completion goal':'Configure event')} onclose={()=>mappingOpen=false}>
        <form onsubmit={e=>{e.preventDefault();void saveMapping()}} oninput={()=>mappingPreview=null}>
          <p class="mono">{eventDraft.event}</p><p class="inspector-note">{t('Give this received event a journey meaning. Relationships come from ordered evidence, not this configuration.')}</p>
          <fieldset class="completion-goal"><legend>{t('Completion goal (optional)')}</legend>
            <p id="completion-goal-help" class="inspector-note">{t('A goal is the event that marks a successful journey, such as Meal added to planner. Exit means the journey ended without claiming success. A goal is separate from Kind.')}</p>
            <label><input type="checkbox" bind:checked={makeGoal} disabled={isCompletionGoal(active,eventDraft)} aria-describedby="completion-goal-help"/>{t('Use this event as the completion goal')}</label>
            {#if isCompletionGoal(active,eventDraft)}<p class="inspector-note">{t('This is the current completion goal. To replace it, choose another event in Mappings & goal.')}</p>{:else if makeGoal}<p class="inspector-note">{t('Activating will make this event the completion goal for new journeys and replace any current goal.')}</p>{:else}<p class="inspector-note">{t('Leave unchecked to map this event without changing the completion goal. Journeys can have no goal.')}</p>{/if}
          </fieldset>
 <p class="inspector-note">{t('A browser intent or generic HTTP success cannot prove persistence. Choose a trusted named commitment or a documented successful operation for that goal.')}</p>
 <fieldset class="event-fields" disabled={unmapEvent}>
